//! Scenarios of the data a person collects besides notes (BUILD-028): a big inbox, calendars with
//! thousands of events, social feeds with thousands of posts. All of it is made here, offline: what
//! the servers would send is parsed from generated bytes and stored in the real stores. The
//! network part (IMAP, CalDAV, the social APIs) is not measured: their pretend servers belong to
//! the tests (they need a test-only certificate), and the time in them is the network's.

use super::content_gen as gen;
use super::scenarios::{frame_body, Body, Fixtures, Prep, Rig, Scenario};
use super::vault_gen::Size;
use crate::app::View;
use crate::calendar::store::{CalendarSource, CalendarStore, SourceKind};
use crate::mail::db::Op;
use crate::mail::store::MailStore;
use std::hint::black_box;
use std::path::{Path, PathBuf};

// ---- mail ------------------------------------------------------------------------------------

/// Put `n` messages into the INBOX of a store at `root` the way a sync does: each message is saved
/// as a file with its search fields, and the index is written in batches of 500.
pub fn fill_mail(root: &Path, n: usize) -> Result<(), String> {
    fill_mail_with(root, &(0..n).map(gen::eml).collect::<Vec<_>>())
}

/// [`fill_mail`] with the messages made already (so that their making is not in a measurement).
pub fn fill_mail_with(root: &Path, messages: &[(Vec<u8>, i64)]) -> Result<(), String> {
    let n = messages.len();
    let store = MailStore::open(root).map_err(|e| e.0)?;
    let account = crate::mail::demo::ACCOUNT;
    let inbox = store.ensure_folder(account, "Bench mail", "INBOX", Some("/"), None, true).map_err(|e| e.0)?;
    store.ensure_folder(account, "Bench mail", "Sent", Some("/"), Some("\\Sent"), true).map_err(|e| e.0)?;
    let f = crate::mail::db::FolderRow { uidvalidity: Some(1), ..inbox };
    let mut ops = Vec::with_capacity(501);
    for (i, (raw, date)) in messages.iter().enumerate() {
        let flags = if i % 3 == 0 { "" } else { "\\Seen" };
        ops.push(Op::message(store.save_message(&f, 1, i as u32 + 1, raw, flags, Some(*date)).map_err(|e| e.0)?));
        if ops.len() == 500 || i + 1 == n {
            ops.push(Op::FolderState { folder: f.id, uidvalidity: Some(1), uidnext: Some(i as u32 + 2), highestmodseq: None, last_sync: 1 });
            store.commit(std::mem::take(&mut ops)).map_err(|e| e.0)?;
        }
    }
    Ok(())
}

fn mail_root(fx: &mut Fixtures) -> Result<PathBuf, String> {
    let n = fx.scale.mail;
    fx.cached("mail", |dir| fill_mail(dir, n))
}

fn inbox_id(store: &MailStore) -> i64 {
    store.reader().and_then(|r| r.folders(None)).expect("the folders are read").into_iter().find(|f| f.name == "INBOX").expect("an INBOX").id
}

fn mail_sync_store(fx: &mut Fixtures) -> Body {
    let (base, messages) = (fx.scratch("mail-sync"), (0..fx.scale.mail).map(gen::eml).collect::<Vec<_>>());
    let mut run = 0;
    Box::new(move || {
        run += 1;
        fill_mail_with(&base.join(format!("run{run}")), &messages).expect("the mail is stored");
    })
}

fn mail_open(fx: &mut Fixtures) -> Prep {
    let root = mail_root(fx)?;
    Ok(Box::new(move || {
        black_box(MailStore::open(&root).expect("the store opens"));
    }))
}

fn mail_list(fx: &mut Fixtures) -> Prep {
    let store = MailStore::open(&mail_root(fx)?).map_err(|e| e.0)?;
    let inbox = inbox_id(&store);
    Ok(Box::new(move || {
        let r = store.reader().expect("a reader");
        black_box(r.list(inbox, 200, 0).expect("a page"));
        black_box(r.list(inbox, 200, 10_000).expect("a deep page"));
        black_box(crate::mail::db::folder_counts(r.conn()).expect("counts"));
    }))
}

fn mail_search(fx: &mut Fixtures) -> Prep {
    let store = MailStore::open(&mail_root(fx)?).map_err(|e| e.0)?;
    Ok(Box::new(move || {
        let r = store.reader().expect("a reader");
        black_box(r.search("project invoice", None, 50, 0).expect("a search"));
        black_box(r.search("garden*", None, 50, 0).expect("a wildcard search"));
    }))
}

fn mail_read(fx: &mut Fixtures) -> Prep {
    let store = MailStore::open(&mail_root(fx)?).map_err(|e| e.0)?;
    let inbox = inbox_id(&store);
    let page = store.reader().and_then(|r| r.list(inbox, 100, 0)).map_err(|e| e.0)?;
    Ok(Box::new(move || {
        for m in &page {
            black_box(store.read_mail(m).expect("the message is read"));
        }
    }))
}

fn mail_rebuild(fx: &mut Fixtures) -> Prep {
    let dir = fx.scratch("mail-rebuild");
    fill_mail(&dir, fx.scale.mail / 4).map_err(|e| e.to_string())?;
    let store = MailStore::open(&dir).map_err(|e| e.0)?;
    Ok(Box::new(move || {
        black_box(store.rebuild_index().expect("the index is rebuilt"));
    }))
}

/// A window with the big inbox: the mail view open.
pub fn mail_rig(fx: &mut Fixtures) -> Result<Rig, String> {
    let root = mail_root(fx)?;
    let g = fx.vault(Size::Small);
    let mut rig = Rig::new(&g);
    rig.app.cfg.mail_accounts = vec![crate::config::MailAccount { id: crate::mail::demo::ACCOUNT.into(), name: "Bench mail".into(), host: "imap.example.com".into(), user: "ada@example.com".into(), ..Default::default() }];
    rig.app.cfg.mail_sync_minutes = 0;
    rig.app.mail.root = root;
    rig.show(View::Mail);
    // the store opens and the folder and message lists load in jobs of their own
    rig.wait("opening the mail store", |app| app.mail.ready_store().is_some())?;
    rig.wait("the list of the inbox", |app| app.mail.total > 0)?;
    rig.run_for(300);
    Ok(rig)
}

fn ui_mail(fx: &mut Fixtures) -> Prep {
    Ok(frame_body(mail_rig(fx)?))
}

// ---- calendar --------------------------------------------------------------------------------

/// A local calendar of `n` events written to a file in `dir`.
pub fn calendar_source(dir: &Path, n: usize) -> CalendarSource {
    let file = dir.join("bench.ics");
    std::fs::write(&file, gen::ics(n)).expect("the calendar file is written");
    CalendarSource { id: "bench".into(), name: "Bench".into(), color: "#4477aa".into(), enabled: true, sync_minutes: 0, kind: SourceKind::Local { file } }
}

fn ics_parse(fx: &mut Fixtures) -> Body {
    let text = gen::ics(fx.scale.events);
    Box::new(move || {
        black_box(crate::calendar::ics::parse_ics(&text));
    })
}

fn ics_write(fx: &mut Fixtures) -> Body {
    let events = crate::calendar::ics::parse_ics(&gen::ics(fx.scale.events));
    Box::new(move || {
        black_box(crate::calendar::ics::to_ics("Bench", &events));
    })
}

fn calendar_load(fx: &mut Fixtures) -> Body {
    let dir = fx.scratch("calendar-load");
    let src = calendar_source(&dir, fx.scale.events);
    Box::new(move || {
        black_box(CalendarStore::new(vec![src.clone()], dir.clone()));
    })
}

fn calendar_occurrences(fx: &mut Fixtures) -> Body {
    let dir = fx.scratch("calendar-occ");
    let store = CalendarStore::new(vec![calendar_source(&dir, fx.scale.events)], dir);
    let from = crate::calendar::time::days_from_civil(2026, 1, 1);
    // a year that shifts by a day each time: the store keeps the ranges it made, this measures making one
    let mut shift = 0;
    Box::new(move || {
        shift = (shift + 1) % 300;
        black_box(store.occurrences(from + shift, from + shift + 365));
    })
}

/// A window with the big calendar: the calendar view open.
pub fn calendar_rig(fx: &mut Fixtures) -> Rig {
    let dir = fx.scratch("calendar-ui");
    let src = calendar_source(&dir, fx.scale.events);
    let g = fx.vault(Size::Small);
    let mut rig = Rig::new(&g);
    rig.app.cfg.calendars = vec![src];
    rig.app.calendar.set_sources(rig.app.cfg.calendars.clone());
    rig.show(View::Calendar);
    rig.run_for(100);
    rig
}

fn ui_calendar(fx: &mut Fixtures) -> Body {
    frame_body(calendar_rig(fx))
}

// ---- social ----------------------------------------------------------------------------------

pub fn posts(n: usize) -> Vec<crate::social::Post> {
    (0..n).filter_map(|i| if i % 2 == 0 { crate::social::mastodon::parse_status(&gen::mastodon_status(i), "https://demo.social") } else { crate::social::bluesky::parse_post_view(&gen::bluesky_post(i)) }).collect()
}

fn social_markup(fx: &mut Fixtures) -> Body {
    let html: Vec<String> = (0..fx.scale.posts).map(gen::post_html).collect();
    Box::new(move || {
        for h in &html {
            black_box(crate::social::markup::html_to_markdown(h));
        }
    })
}

fn social_mastodon(fx: &mut Fixtures) -> Body {
    let items: Vec<_> = (0..fx.scale.posts).map(gen::mastodon_status).collect();
    Box::new(move || {
        for v in &items {
            black_box(crate::social::mastodon::parse_status(v, "https://demo.social"));
        }
    })
}

fn social_bluesky(fx: &mut Fixtures) -> Body {
    let items: Vec<_> = (0..fx.scale.posts).map(gen::bluesky_post).collect();
    Box::new(move || {
        for v in &items {
            black_box(crate::social::bluesky::parse_post_view(v));
        }
    })
}

fn social_index_add(fx: &mut Fixtures) -> Body {
    let posts = posts(fx.scale.posts);
    Box::new(move || {
        let mut index = crate::social::post_index::PostIndex::in_memory();
        index.add("bench", "home", &posts);
        black_box(&index);
    })
}

fn social_index_search(fx: &mut Fixtures) -> Body {
    let posts = posts(fx.scale.posts);
    let mut index = crate::social::post_index::PostIndex::in_memory();
    index.add("bench", "home", &posts);
    Box::new(move || {
        black_box(index.search_wild("garden*", 50));
        black_box(index.search_wild("plan river", 50));
    })
}

/// A window with feeds of many posts: the feed view open.
pub fn social_rig(fx: &mut Fixtures) -> Rig {
    let g = fx.vault(Size::Small);
    let mut rig = Rig::new(&g);
    let demo = crate::social::demo::account();
    let id = demo.account.id.clone();
    rig.app.cfg.social_accounts = vec![demo.clone()];
    rig.app.social.load_demo(&demo);
    if let Some(t) = rig.app.social.timelines.get_mut(&(id, "home".into())) {
        t.posts = posts(fx.scale.posts);
    }
    rig.show(View::Social(None));
    rig.run_for(100);
    rig
}

fn ui_social(fx: &mut Fixtures) -> Body {
    frame_body(social_rig(fx))
}

pub fn list() -> Vec<Scenario> {
    let (p, m) = (Scenario::plain, Scenario::maybe);
    vec![
        p("mail.sync.store.large", 1, true, mail_sync_store).cold(),
        m("mail.open.large", 5, false, mail_open),
        m("mail.list.large", 20, true, mail_list),
        m("mail.search.large", 10, true, mail_search),
        m("mail.read.message", 10, false, mail_read),
        m("mail.index.rebuild.large", 1, false, mail_rebuild).cold(),
        m("ui.frame.mail.large", 30, false, ui_mail),
        p("calendar.ics.parse.large", 10, true, ics_parse),
        p("calendar.ics.write.large", 10, false, ics_write),
        p("calendar.store.load.large", 10, false, calendar_load),
        // version 2: the year shifts by a day each iteration (the store keeps the ranges it made), version 1 asked for one year again and again
        p("calendar.occurrences.year.large", 5, true, calendar_occurrences).version(2),
        p("ui.frame.calendar.large", 30, false, ui_calendar),
        p("social.markup.html.large", 10, false, social_markup),
        p("social.mastodon.parse.large", 10, false, social_mastodon),
        p("social.bluesky.parse.large", 10, false, social_bluesky),
        p("social.index.add.large", 3, false, social_index_add),
        p("social.index.search.large", 10, false, social_index_search),
        p("ui.frame.social.large", 30, false, ui_social),
    ]
}
